import { Group, Mesh, PlaneGeometry, CylinderGeometry, TorusKnotGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, DirectionalLight, AmbientLight, Color, Texture, DoubleSide } from 'three/webgpu';
import { uv, mix, lessThan, float, vec3, select, sub, div, length, mul, vec2, step } from 'three/tsl';
import { gsap } from 'gsap';
import { orbit } from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  // ------------------------------------------------------------------------
  // Helpers
  // ------------------------------------------------------------------------
  const toColor = (hex) => new ctx.THREE.Color(hex);
  const colors = (config.colors ?? config.visual?.colors) || {};
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const getStop = (i) => gradientStops[i] ?? { at: 0, hex: '#000000' };
  const bottomCol = toColor(getStop(0).hex);
  const midCol = toColor(getStop(1).hex);
  const topCol = toColor(getStop(2).hex);

  // ------------------------------------------------------------------------
  // Root group
  // ------------------------------------------------------------------------
  const root = new Group();

  // ------------------------------------------------------------------------
  // Backdrop with vertical gradient (Plane at z = -3)
  // ------------------------------------------------------------------------
  const backdropGeom = new PlaneGeometry(7, 6);
  const uvNode = uv();
  const y = uvNode.y;

  const bottomColorNode = vec3(bottomCol.r, bottomCol.g, bottomCol.b);
  const midColorNode = vec3(midCol.r, midCol.g, midCol.b);
  const topColorNode = vec3(topCol.r, topCol.g, topCol.b);

  const cond = lessThan(y, float(0.7));
  const tLow = y.div(float(0.7));
  const tHigh = y.sub(float(0.7)).div(float(0.3));
  const lowMix = mix(bottomColorNode, midColorNode, tLow);
  const highMix = mix(midColorNode, topColorNode, tHigh);
  const gradColor = select(cond, lowMix, highMix);

  const backdropMat = new MeshBasicNodeMaterial({
    color: gradColor,
    side: DoubleSide,
    depthWrite: false,
  });
  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.z = -3;
  root.add(backdropMesh);

  // ------------------------------------------------------------------------
  // Pedestal cylinder
  // ------------------------------------------------------------------------
  const pedestalGeom = new CylinderGeometry(1.1, 1.1, 0.5, 32);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: toColor('#14141a'),
    roughness: 0.7,
    metalness: 0.35,
    side: DoubleSide,
  });
  const pedestalMesh = new Mesh(pedestalGeom, pedestalMat);
  // top face at y = -0.35 -> center y = -0.35 - height/2
  pedestalMesh.position.y = -0.35 - 0.25;
  root.add(pedestalMesh);

  // ------------------------------------------------------------------------
  // Torus Knot (hero)
  // ------------------------------------------------------------------------
  const knotGeom = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshStandardNodeMaterial({
    color: 0xffffff,
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    side: DoubleSide,
  });
  const knotMesh = new Mesh(knotGeom, knotMat);
  knotMesh.position.set(0, 0.4, 0);
  root.add(knotMesh);

  // Load brushed metal roughness map and apply
  let brushedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      brushedTex = tex;
      knotMat.roughnessMap = tex;
      knotMat.needsUpdate = true;
    });
  }

  // ------------------------------------------------------------------------
  // Contact shadow (simple radial fade)
  // ------------------------------------------------------------------------
  const shadowPlaneGeom = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: vec3(0, 0, 0),
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  // Node based radial alpha
  const uvS = uv();
  const centered = sub(uvS, vec2(0.5, 0.5));
  const dist = length(centered);
  const radius = float(0.5); // half of plane size in uv space
  const falloff = float(0.4 / 3); // normalized falloff distance
  const alpha = float(0.6).mul( float(1).sub( smoothstep(radius, radius + falloff, dist ) ) );
  shadowMat.opacityNode = alpha; // attach opacity node (supported by node material)
  const shadowMesh = new Mesh(shadowPlaneGeom, shadowMat);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.y = -0.36;
  root.add(shadowMesh);

  // ------------------------------------------------------------------------
  // Lights
  // ------------------------------------------------------------------------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);

  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(3, 4, 3);
  root.add(keyLight);

  const rimLight = new DirectionalLight(toColor('#ff2a38'), 0.8);
  rimLight.position.set(-3, -2, -3);
  root.add(rimLight);

  // ------------------------------------------------------------------------
  // Text
  // ------------------------------------------------------------------------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const role = item.role?.toLowerCase() ?? 'body';
    const opts = {
      fontSize: item.typography?.fontSize ?? (role === 'headline' ? 68 : 18),
      color: role === 'headline' ? '#e8ecf2' : '#e8ecf2',
      align: 'center',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // Positioning
    const baselineOffset = role === 'headline' ? -1.2 : -1.6;
    txtObj.position.set(0, baselineOffset, 0);
    root.add(txtObj);
  }

  // ------------------------------------------------------------------------
  // Cinematic primitives
  // ------------------------------------------------------------------------
  const primitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name && ctx.primitives[prim.name]) {
        const p = ctx.primitives[prim.name](root, prim.params || {});
        primitives.push(p);
      }
    }
  }

  // ------------------------------------------------------------------------
  // Cleanup
  // ------------------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    // Dispose geometries & materials
    backdropGeom.dispose();
    backdropMat.dispose();
    pedestalGeom.dispose();
    pedestalMat.dispose();
    knotGeom.dispose();
    knotMat.dispose();
    shadowPlaneGeom.dispose();
    shadowMat.dispose();
    // Dispose loaded texture
    if (brushedTex) brushedTex.dispose();
    // Cleanup primitives
    for (const p of primitives) {
      if (p.cleanup) p.cleanup();
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return root;
}
